css:
:root {
	--ink: #2b2d42;
	--paper: #edf2f4;
	--accent: #d90429;
	--gap: 20px;
}

body {
	margin: 0;
	font-family: sans-serif;
}

h1 {
	font-size: 26px;
	font-weight: 700;
	color: var(--ink);
}

.panel {
	padding: var(--gap);
	background: var(--paper);
}

.chip {
	display: block;
	margin-top: 12px;
	padding: 8px 12px;
	border-radius: 8px;
	background: var(--accent);
	color: #ffffff;
	font-size: 16px;
	text-decoration: none;
}

.note.mk-19m2fp9 {
				margin-top: var(--gap);
				padding: 8px 12px;
				border-left: 4px solid var(--accent);
				color: var(--ink);
				font-size: 16px;
			}
